AND company_id IN
#{candidateId}

SELECT DISTINCT candidate.company_id FROM person_edge edge JOIN person candidate ON (candidate.id = edge.source_person_id OR candidate.id = edge.target_person_id) AND candidate.workspace_id = #{workspaceId} AND candidate.suspended_at IS NULL AND candidate.provision_ceased_at IS NULL AND candidate.archived_at IS NULL AND candidate.company_id IN
#{candidateId}
JOIN person engaged ON engaged.id = IF(candidate.id = edge.source_person_id, edge.target_person_id, edge.source_person_id) AND engaged.archived_at IS NULL AND engaged.suspended_at IS NULL AND (engaged.workspace_id = #{workspaceId} OR EXISTS ( SELECT 1 FROM person_share engaged_share JOIN workspace viewer_workspace ON viewer_workspace.id = engaged_share.workspace_id JOIN workspace owner_workspace ON owner_workspace.id = engaged.workspace_id AND owner_workspace.org_id = viewer_workspace.org_id WHERE engaged_share.person_id = engaged.id AND engaged_share.workspace_id = #{workspaceId} )) WHERE edge.workspace_id = #{workspaceId} AND edge.strength >= #{strongEdge} AND edge.source_person_id <> edge.target_person_id AND EXISTS ( SELECT 1 FROM activity engaged_activity WHERE engaged_activity.workspace_id = #{workspaceId} AND engaged_activity.person_id = engaged.id UNION ALL SELECT 1 FROM note engaged_note WHERE engaged_note.workspace_id = #{workspaceId} AND engaged_note.visibility = 'workspace' AND engaged_note.person_id = engaged.id UNION ALL SELECT 1 FROM task engaged_task WHERE engaged_task.workspace_id = #{workspaceId} AND engaged_task.person_id = engaged.id ) AND NOT EXISTS ( SELECT 1 FROM activity user_activity WHERE user_activity.workspace_id = #{workspaceId} AND user_activity.created_by_id = #{userId} AND (user_activity.person_id IS NULL OR EXISTS ( SELECT 1 FROM person processable WHERE processable.id = user_activity.person_id AND processable.suspended_at IS NULL AND processable.provision_ceased_at IS NULL AND processable.archived_at IS NULL AND (processable.workspace_id = #{workspaceId} OR EXISTS ( SELECT 1 FROM person_share processable_share JOIN workspace processable_viewer_workspace ON processable_viewer_workspace.id = processable_share.workspace_id JOIN workspace processable_owner_workspace ON processable_owner_workspace.id = processable.workspace_id AND processable_owner_workspace.org_id = processable_viewer_workspace.org_id WHERE processable_share.person_id = processable.id AND processable_share.workspace_id = #{workspaceId} )) )) AND ( user_activity.person_id IN ( SELECT company_person.id FROM person company_person WHERE company_person.workspace_id = #{workspaceId} AND company_person.company_id = candidate.company_id AND company_person.suspended_at IS NULL AND company_person.provision_ceased_at IS NULL AND company_person.archived_at IS NULL ) OR user_activity.deal_id IN ( SELECT company_deal.id FROM deal company_deal WHERE company_deal.workspace_id = #{workspaceId} AND company_deal.company_id = candidate.company_id ) ) )

